<script lang="ts">
 import { onMount } from 'svelte'; import { request } from '../../../lib/api'; import { PageHeader } from '../../../lib/ui';
 type Field={key:string;label:string;kind:string;required:boolean;options:string[]};type Template={id:string;title:string;description:string;fields:Field[]};let templates=$state<Template[]>([]),selected=$state<Template|null>(null),values=$state<Record<string,string>>({}),error=$state(''),saving=$state(false);
 async function load(){try{templates=(await request<{templates:Template[]}>('/v1/forms')).templates;}catch(cause){error=cause instanceof Error?cause.message:'Form tidak dapat dimuat.';}} async function choose(form:Template){selected=form;values=Object.fromEntries(form.fields.map(field=>[field.key,'']));}async function submit(){if(!selected)return;saving=true;try{await request(`/v1/forms/${selected.id}/submissions`,{method:'POST',body:JSON.stringify({payload:values})});selected=null;await load();}catch(cause){error=cause instanceof Error?cause.message:'Form tidak dapat dikirim.';}finally{saving=false;}}onMount(load);
</script><main class="workspace-page" id="main-content" tabindex="-1"><PageHeader title="Form kerja" description="Isi formulir aktif yang relevan dengan pekerjaan Anda." backHref="/app"/>{#if error}<p class="alert">{error}</p>{/if}{#if selected}<section class="panel"><h2>{selected.title}</h2><p>{selected.description}</p><form novalidate onsubmit={(e)=>{e.preventDefault();submit();}}>{#each selected.fields as field}<label>{field.label}{field.required?' *':''}{#if field.kind==='textarea'}<textarea bind:value={values[field.key]} required={field.required}></textarea>{:else if field.kind==='select'}<select bind:value={values[field.key]} required={field.required}><option value="">Pilih</option>{#each field.options as option}<option value={option}>{option}</option>{/each}</select>{:else}<input type={field.kind} bind:value={values[field.key]} required={field.required}/>{/if}</label>{/each}<button disabled={saving}>Kirim form</button></form></section>{:else}<section class="panel list">{#each templates as form (form.id)}<button onclick={()=>choose(form)}><strong>{form.title}</strong><small>{form.description}</small></button>{:else}<p>Belum ada form aktif.</p>{/each}</section>{/if}</main><style>.workspace-page{display:grid;gap:12px}.panel{padding:16px;border-radius:var(--radius);max-width:720px}form{display:grid;gap:10px}label{display:grid;gap:5px;font-size:13px}textarea{min-height:90px}.list{display:grid;gap:8px}.list button{text-align:left}.list small,p{display:block;color:var(--muted);margin-top:4px}.alert{color:var(--danger)}</style>
